# area: narrowing_user
# hypothesis: a TypeIs guard defined in a nested scope narrows the else branch to the complement type, a TypeGuard guard leaves the else branch at the full declared union, and TypeIs also narrows attribute access.
from typing import TypeGuard, TypeIs, assert_type


def is_str(v: object) -> TypeIs[str]:
    return isinstance(v, str)


def is_str_guard(v: object) -> TypeGuard[str]:
    return isinstance(v, str)


def is_int(v: object) -> TypeIs[int]:
    return isinstance(v, int)


class Box:
    def __init__(self, item: int | None) -> None:
        self.item = item


def outer() -> None:
    def check(x: int | str) -> str:
        if is_str(x):
            assert_type(x, str)
            return x
        else:
            assert_type(x, int)
            return str(x)

    def check_guard(x: int | str) -> str:
        if is_str_guard(x):
            assert_type(x, str)
            return x
        else:
            assert_type(x, int | str)
            return str(x)

    print(check(3), check('a'), check_guard(4))


def attr(b: Box) -> str:
    if is_int(b.item):
        assert_type(b.item, int)
        return 'int'
    else:
        assert_type(b.item, None)
        return 'none'


def wrong(x: int | str) -> None:
    if is_str(x):
        assert_type(x, int)  # expect-error


outer()
print(attr(Box(3)), attr(Box(None)))
wrong('a')
